mapper.select:
SELECT event.event_sequence AS sequence, event.schema_id, event.canonical_json
FROM public.agent_runtime_execution_events event
JOIN public.agent_runtime_execution_runs run
  ON run.tenant_id=event.tenant_id AND run.run_id=event.run_id AND run.session_id=event.session_id
WHERE event.tenant_id=#{owner.sessionRef.tenantId.value}
  AND event.session_id=#{owner.sessionRef.sessionId}
  AND event.type=#{eventType}
  AND run.target_kind=#{owner.target.kind} AND run.target_id=#{owner.target.id}

      AND run.end_user_id IS NULL
      AND run.end_user_id=#{owner.requireUser.value}

  AND event.event_sequence > #{after}
ORDER BY event.event_sequence
LIMIT #{limit}
